#!/usr/bin/env bun
// Generate assets/skills/consultation/SKILL.md from the repo-only skill sources.
//
// Run: bun run gen:skill   (also invoked by script/build.ts before bundling)
//
// The generated file is the only skill asset that ships; skill-src/ never does.
// A module file may hold more than one part, separated by a `<!-- part -->`
// line, because a mode's workflow section and its output template are not
// adjacent in the generated document. MODULES fixes the emitted order.

import { mkdir, readFile, rename, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"

const REPO_ROOT = join(import.meta.dir, "..")

export const SKILL_SRC_DIR = join(REPO_ROOT, "skill-src/consultation")
export const SKILL_OUTPUT_PATH = join(REPO_ROOT, "assets/skills/consultation/SKILL.md")

export const GENERATED_MARKER =
  "<!-- generated by script/gen-skill.ts from skill-src/consultation; do not edit -->"

export const MODE_ROUTING_MARKER = "<!-- MODE-ROUTING -->"

export const MODE_ROUTING_ASSET = join(REPO_ROOT, "assets/principles/mode-routing.md")

export const CLAIM_TYPES_MARKER = "<!-- CLAIM-TYPES -->"

export const CLAIM_TYPES_ASSET = join(REPO_ROOT, "assets/principles/claim-types.md")

export const SOURCE_CRITERIA_MARKER = "<!-- SOURCE-CRITERIA -->"

export const SOURCE_CRITERIA_ASSET = join(REPO_ROOT, "assets/principles/source-criteria.md")

export const CHANNEL_POLICY_MARKER = "<!-- CHANNEL-POLICY -->"

export const CHANNEL_POLICY_ASSET = join(REPO_ROOT, "assets/principles/channel-policy.md")

export interface SkillFragment {
  readonly name: string
  /** The placeholder left in a skill-src module, replaced at generation. */
  readonly marker: string
  readonly assetPath: string
}

/**
 * Shared principle fragments injected into the generated skill. Each must
 * appear exactly once in a skill-src module; a missing, empty, or repeated
 * marker is a build error so the generated skill cannot silently lose a
 * fragment or carry two copies of it.
 */
export const SKILL_FRAGMENTS: readonly SkillFragment[] = [
  { name: "mode-routing", marker: MODE_ROUTING_MARKER, assetPath: MODE_ROUTING_ASSET },
  { name: "claim-types", marker: CLAIM_TYPES_MARKER, assetPath: CLAIM_TYPES_ASSET },
  { name: "source-criteria", marker: SOURCE_CRITERIA_MARKER, assetPath: SOURCE_CRITERIA_ASSET },
  { name: "channel-policy", marker: CHANNEL_POLICY_MARKER, assetPath: CHANNEL_POLICY_ASSET },
]

const PART_SEPARATOR = /\n\s*<!-- part -->\s*\n/

export interface SkillModuleRef {
  readonly file: string
  /** 1-based part index for a module file that holds multiple parts. */
  readonly part?: number
}

/**
 * Emitted module order. Repeated files are intentional: `modes/research.md`,
 * `modes/author.md`, and `policies/output-and-memory.md` each contribute both
 * an early workflow chunk and a later template/record chunk.
 */
export const MODULES: readonly SkillModuleRef[] = [
  { file: "core.md" },
  { file: "policies/team-orchestration.md" },
  { file: "policies/evidence-and-sources.md" },
  { file: "policies/risk-and-counter-evidence.md" },
  { file: "modes/research.md", part: 1 },
  { file: "modes/author.md", part: 1 },
  { file: "policies/current-state-docs.md" },
  { file: "modes/design.md", part: 1 },
  { file: "policies/output-and-memory.md", part: 1 },
  { file: "modes/select.md" },
  { file: "modes/verify.md" },
  { file: "modes/plan.md" },
  { file: "modes/research.md", part: 2 },
  { file: "modes/guide.md" },
  { file: "modes/author.md", part: 2 },
  { file: "modes/design.md", part: 2 },
  { file: "policies/output-and-memory.md", part: 2 },
]

function moduleParts(raw: string): string[] {
  return raw.split(PART_SEPARATOR).map((part) => part.trim())
}

async function loadFragment(fragment: SkillFragment): Promise<string> {
  let raw: string
  try {
    raw = await readFile(fragment.assetPath, "utf8")
  } catch {
    throw new Error(`fragment for ${fragment.marker} not found: ${fragment.assetPath}`)
  }
  const text = raw.trim()
  if (text.length === 0) {
    throw new Error(`fragment for ${fragment.marker} is empty: ${fragment.assetPath}`)
  }
  return text
}

/**
 * Replace every fragment marker with its shared source. A missing or
 * duplicated marker is a build error naming the marker: the generated skill
 * must carry each fragment exactly once, from the one source of truth.
 */
export async function injectMarkers(
  body: string,
  fragments: readonly SkillFragment[] = SKILL_FRAGMENTS,
): Promise<string> {
  let result = body
  for (const fragment of fragments) {
    const occurrences = result.split(fragment.marker).length - 1
    if (occurrences === 0) {
      throw new Error(`skill-src/consultation is missing the ${fragment.marker} marker`)
    }
    if (occurrences > 1) {
      throw new Error(
        `skill-src/consultation repeats the ${fragment.marker} marker ${occurrences} times`,
      )
    }
    const text = await loadFragment(fragment)
    result = result.replace(fragment.marker, () => text)
  }
  return result
}

/** Render the full skill file without touching disk. */
export async function renderSkill(
  srcDir: string = SKILL_SRC_DIR,
  fragments: readonly SkillFragment[] = SKILL_FRAGMENTS,
): Promise<string> {
  const frontMatter = (await readFile(join(srcDir, "front-matter.md"), "utf8")).trim()
  if (!frontMatter.startsWith("---") || !frontMatter.endsWith("---")) {
    throw new Error("skill-src/consultation/front-matter.md must be a YAML front-matter block")
  }

  const chunks: string[] = []
  for (const entry of MODULES) {
    const raw = await readFile(join(srcDir, entry.file), "utf8")
    const parts = moduleParts(raw)
    if (entry.part !== undefined) {
      const part = parts[entry.part - 1]
      if (part === undefined || part.length === 0) {
        throw new Error(`module ${entry.file} has no non-empty part ${entry.part}`)
      }
      chunks.push(part)
      continue
    }
    if (parts.length !== 1) {
      throw new Error(
        `module ${entry.file} holds ${parts.length} parts; select one in MODULES with \`part\``,
      )
    }
    const [only] = parts
    if (only === undefined || only.length === 0) {
      throw new Error(`module ${entry.file} is empty`)
    }
    chunks.push(only)
  }

  const body = await injectMarkers(chunks.join("\n\n"), fragments)

  return `${frontMatter}\n${GENERATED_MARKER}\n\n${body}\n`
}

/** Atomically write the generated skill file. */
export async function writeSkillFile(
  outputPath: string = SKILL_OUTPUT_PATH,
  srcDir: string = SKILL_SRC_DIR,
): Promise<string> {
  const rendered = await renderSkill(srcDir)
  await mkdir(dirname(outputPath), { recursive: true })
  const tmpPath = `${outputPath}.tmp`
  await writeFile(tmpPath, rendered, "utf8")
  await rename(tmpPath, outputPath)
  return outputPath
}

if (import.meta.main) {
  const path = await writeSkillFile()
  console.log(`generated skill: ${path}`)
}
